/**
 * Extract Manifest URL for Workflow 3 - Normalize webhook data structure
 * Handles both webhook body structure (first pass) and direct fields
 * FIX: Check top-level first (Wait node), then body (webhook), process ALL items
 * Handle null values properly - construct from orderId if manifestUrl is null
 * UPDATED: Uses 2B manifest (not 2A) and includes needed info for Workflow 3
 */
const inputs = $input.all();

return inputs.map(item => {
  const input = item.json;

  // Priority: Check top-level first (Wait node resume), then body (webhook first pass)
  // Wait node data has manifestUrl at top level, webhook has it in body
  // Handle null/empty string explicitly
  let manifestUrl = (input.manifestUrl && input.manifestUrl !== null && input.manifestUrl !== '') ? input.manifestUrl : null;
  if (!manifestUrl) {
    manifestUrl = (input.originalManifestUrl && input.originalManifestUrl !== null && input.originalManifestUrl !== '') ? input.originalManifestUrl : null;
  }

  let orderId = (input.orderId && input.orderId !== null && input.orderId !== '') ? input.orderId : null;
  if (!orderId) {
    orderId = (input.amazonOrderId && input.amazonOrderId !== null && input.amazonOrderId !== '') ? input.amazonOrderId : null;
  }

  // Fallback: Extract orderId from manifestKey if available (S3 node might have stripped orderId)
  if ((!orderId || orderId === null || orderId === '') && input.manifestKey) {
    const manifestKeyStr = String(input.manifestKey).trim();
    if (manifestKeyStr && manifestKeyStr !== 'null' && manifestKeyStr !== 'undefined') {
      // Try multiple patterns: /orders/{orderId}/ or orders/{orderId}/
      const patterns = [
        /[\/]orders[\/]([^\/]+)[\/]/,  // Matches /orders/TEST-ORDER-006/
        /orders[\/]([^\/]+)[\/]/,     // Matches orders/TEST-ORDER-006/
      ];

      for (const pattern of patterns) {
        const keyMatch = manifestKeyStr.match(pattern);
        if (keyMatch && keyMatch[1]) {
          orderId = keyMatch[1];
          console.log(`✓ Extracted orderId from manifestKey: ${orderId} (pattern matched)`);
          break;
        }
      }

      if (!orderId) {
        console.warn(`⚠️ Could not extract orderId from manifestKey: ${manifestKeyStr.substring(0, 100)}`);
      }
    }
  }

  let webhookUrl = (input.webhookUrl && input.webhookUrl !== null && input.webhookUrl !== '') ? input.webhookUrl : null;

  // If not found at top level, check body (webhook structure)
  if (!manifestUrl && input.body && input.body !== input) {
    manifestUrl = (input.body.manifestUrl && input.body.manifestUrl !== null && input.body.manifestUrl !== '') ? input.body.manifestUrl : null;
    if (!manifestUrl) {
      manifestUrl = (input.body.originalManifestUrl && input.body.originalManifestUrl !== null && input.body.originalManifestUrl !== '') ? input.body.originalManifestUrl : null;
    }
    if (!orderId) {
      orderId = (input.body.orderId && input.body.orderId !== null && input.body.orderId !== '') ? input.body.orderId : null;
      if (!orderId) {
        orderId = (input.body.amazonOrderId && input.body.amazonOrderId !== null && input.body.amazonOrderId !== '') ? input.body.amazonOrderId : null;
      }
    }
    if (!webhookUrl) {
      webhookUrl = (input.body.webhookUrl && input.body.webhookUrl !== null && input.body.webhookUrl !== '') ? input.body.webhookUrl : null;
    }
  }

  // If no manifestUrl but we have orderId, construct it
  // UPDATED: Uses 2B manifest (not 2A) for Workflow 3
  if ((!manifestUrl || manifestUrl === null || manifestUrl === '') && orderId && orderId !== null && orderId !== '') {
    // PRODUCTION URL: https://admin.littleherolabs.com
    // PREVIEW URL: https://387cb69b.little-hero-labs-admin.pages.dev (for testing preview branches)
    const baseUrl = 'https://admin.littleherolabs.com/api/manifests';
    manifestUrl = `${baseUrl}/book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2b-manifest.json`;
    console.log(`✓ Constructed manifestUrl from orderId: ${manifestUrl} (orderId was: ${orderId})`);
  }

  // Final validation - if still no manifestUrl, we have a problem
  if (!manifestUrl || manifestUrl === null || manifestUrl === '') {
    const keys = input ? Object.keys(input).join(', ') : 'no input';
    const manifestUrlValue = input.manifestUrl;
    const orderIdValue = orderId;  // Use the extracted orderId, not input.orderId
    const manifestKeyValue = input.manifestKey || 'not present';
    console.error(`❌ Cannot resolve manifestUrl. manifestUrl=${manifestUrlValue}, orderId=${orderIdValue}, manifestKey=${manifestKeyValue}, Keys: ${keys}`);
    throw new Error(`Cannot resolve manifestUrl. manifestUrl=${manifestUrlValue}, orderId=${orderIdValue}, manifestKey=${manifestKeyValue}, Keys: ${keys}`);
  }

  // CRITICAL: Detect if this is from webhook (first pass) or Wait node (retry loop)
  // On webhook: body.webhookUrl exists, isFirstPass is undefined
  // On Wait node resume: isFirstPass is explicitly false (from Restore JSON After Upload)
  let isFirstPass = input.isFirstPass;
  if (isFirstPass === undefined) {
    // Not set yet - check if this is from webhook (first pass) or Wait node (retry loop)
    // Check for webhookUrl in body (webhook structure) or top-level (already extracted)
    const hasWebhookUrl = !!(webhookUrl || (input.body && input.body !== input && input.body.webhookUrl));
    isFirstPass = hasWebhookUrl ? true : false; // Default to false if we can't determine
  }

  // CRITICAL: Preserve all fields from input, especially isFirstPass, statusUrl, etc.
  // These are essential for routing in the IF node after retry loops
  // Also include manifestKey for downstream nodes
  const manifestKey = `book-mvp-simple-adventure/orders/${orderId}/manifests/2b-manifest.json`;

  return {
    json: {
      ...input,  // Preserve ALL fields from input
      manifestUrl: manifestUrl,
      originalManifestUrl: manifestUrl,
      manifestKey: manifestKey,
      orderId: orderId || input.orderId || input.amazonOrderId || null,
      webhookUrl: webhookUrl || input.webhookUrl || null,
      // Explicitly preserve these critical fields for IF node routing
      isFirstPass: isFirstPass,
      statusUrl: input.statusUrl || input.status_url || null,
      status_url: input.status_url || input.statusUrl || null,
      requestId: input.requestId || input.request_id || null,
      request_id: input.request_id || input.requestId || null,
      poseNumber: input.poseNumber || null,
      characterHash: input.characterHash || null,
      // Include backend URL for downstream proxy URL construction
      backendUrl: 'https://admin.littleherolabs.com'
    }
  };
});

/**
 * Build Assembly Input From Manifest
 * Converts 2B manifest into the payload expected downstream.
 */
const input = $input.first().json || {};
const manifest = input || {}; // HTTP node passes manifest JSON as item

// Try to get preserved context from Extract node
let ctx = {};
try { ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {}; } catch {}

const order = manifest.order || {};
const entries = Array.isArray(manifest.entries) ? manifest.entries : [];
const amazonOrderId = order.amazonOrderId || ctx.orderId || null;
const characterHash = manifest.characterHash || order.characterHash || null;
const backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';

if (!amazonOrderId || !characterHash) {
  throw new Error('Manifest missing amazonOrderId or characterHash');
}

const toProxy = (key) => `${backendUrl}/api/assets/${key}`;
const processedImages = entries
  .filter(e => Number.isFinite(Number(e.poseNumber)) && e.bgRemovedKey)
  .sort((a,b) => a.poseNumber - b.poseNumber)
  .map(e => ({
    poseNumber: e.poseNumber,
    fileName: (e.bgRemovedKey.split('/').pop()) || `pose${String(e.poseNumber).padStart(2,'0')}_nobg.png`,
    r2Path: e.bgRemovedKey,
    publicUrl: toProxy(e.bgRemovedKey),
    briaProcessed: true,
    briaStatus: 'COMPLETED',
    processingError: false,
  }));

return [{ json: {
  amazonOrderId,
  characterHash,
  characterSpecs: order.characterSpecs || {},
  bookSpecs: order.bookSpecs || {},
  orderDetails: order.orderDetails || {},
  publicR2Url: order.publicR2Url || null,
  backendUrl,
  processedImages
} }];

// Get order ready for book assembly (robust Webhook body handling)

// Webhook puts the real payload under .body; if not present, assume it's already flat
const input = $input.first().json;
const payload = input.body ?? input;

// Pull required fields from either flat or nested orderData
const amazonOrderId = payload.amazonOrderId ?? payload.orderData?.amazonOrderId ?? null;
const characterHash = payload.characterHash ?? payload.orderData?.characterHash ?? null;

// Optional sections
const characterSpecs = payload.characterSpecs ?? payload.orderData?.characterSpecs ?? {};
const bookSpecs      = payload.bookSpecs      ?? payload.orderData?.bookSpecs      ?? {};
const orderDetails   = payload.orderDetails   ?? payload.orderData?.orderDetails   ?? {};
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url    = payload.publicR2Url    ?? null;

// Processed images come in flat (2B sends them at top level)
const processedImages = payload.processedImages ?? [];

// Validate
if (!amazonOrderId || !characterHash) {
  throw new Error('Missing required order data: amazonOrderId or characterHash');
}
if (!Array.isArray(processedImages) || processedImages.length === 0) {
  throw new Error('No processed images received from Workflow 2B');
}

// Normalize/initialize assembly state
const assemblingOrder = {
  status: 'book_assembly_in_progress',
  assemblyStartedAt: new Date().toISOString(),
  pagesGenerated: 0,
  totalPagesRequired: 14,
  assemblyProgress: 0,

  amazonOrderId,
  characterHash,
  characterSpecs,
  bookSpecs,
  orderDetails,
  publicR2Url,

  processedImages
};

console.log(`Starting book assembly for order: ${amazonOrderId} (images: ${processedImages.length})`);
return [{ json: assemblingOrder }];

/**
 * Load Background Images (pages 1..14)
 * Uses backend proxy URLs for R2 assets. Backgrounds live at:
 *   little-hero-assets/book-mvp-simple-adventure/backgrounds/pageXX-<slug>.png
 */
const order = $input.first().json || {};

// Get backendUrl from context or use default
let backendUrl = order.backendUrl;
if (!backendUrl) {
  try {
    const ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {};
    backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
  } catch {
    backendUrl = 'https://admin.littleherolabs.com';
  }
}

if (!order.amazonOrderId) {
  throw new Error('Amazon Order ID is required for loading background images');
}

// Keep slugs in lockstep with your storage names.
const sceneSlugs = [
  'twilight-walk','night-forest','magic-doorway','courage-leap','morning-meadow',
  'tall-forest','mountain-vista','picnic-surprise','beach-discovery','crystal-cave',
  'giant-flowers','almost-there','animal-reveal','flying-home'
];
const sceneNames = [
  'twilight_walk','night_forest','magic_doorway','courage_leap','morning_meadow',
  'tall_forest','mountain_vista','picnic_surprise','beach_discovery','crystal_cave',
  'giant_flowers','enchanted_grove','animal_reveal','flying_home'
];

// Construct backend proxy URLs for backgrounds
const backgroundImages = Array.from({ length: 14 }, (_, i) => {
  const pageNumber = i + 1;
  const r2Key = `book-mvp-simple-adventure/backgrounds/page${String(pageNumber).padStart(2,'0')}-${sceneSlugs[i]}.png`;
  const imagePath = `${backendUrl}/api/assets/${r2Key}`;
  return {
    pageNumber,
    imagePath,
    sceneName: sceneNames[i],
    validated: false,
  };
});

return [{ json: { ...order, backgroundImages, backendUrl } }];

/**
 * Load story text (14 pages) + ensure characterImages exists
 * Belt-and-suspenders: synthesize from processedImages or canonical paths.
 */
const order = $input.first().json || {};
const childName = order.characterSpecs?.childName;
const hometown  = order.characterSpecs?.hometown || 'Seattle';
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url = order.publicR2Url || null;
const BASE_PREFIX = 'book-mvp-simple-adventure/order-generated-assets/characters';

if (!childName) throw new Error('Child name required (characterSpecs.childName)');
const hash = order.characterHash || order.orderData?.characterHash;
if (!hash) throw new Error('Missing characterHash in order payload');

// 1) Story lines (unchanged)
const lines = [
  `It was a nice night in ${hometown}. ${childName} went outside.`,
  `${childName} looked at the stars.<br>You like to explore, the voice said.`,
  `There was a doorway! ${childName} walked through.`,
  `Stars were all around! ${childName} felt brave.`,
  `${childName} noticed footprints and followed them.`,
  `The path went through giant trees. ${childName} felt small, but not scared.`,
  `Look how far you came, the voice said.`,
  `Lunch was waiting! ${childName} ate happily.<br>You earned this, the voice said.`,
  `The path became warm sand. Look down there, the voice said.<br>${childName} found a beautiful shell!`,
  `${childName} found a cave with sparkly crystals! They glowed with rainbow colors. You can find beauty everywhere, the voice said.`,
  `The path went through giant flowers. The petals were SO big!<br>You make others happy, the voice said.`,
  `The voice felt very close now. You are perfect just as you are, it said.<br>${childName} looked around. Where was the voice?`,
  `Tiger appeared! It was the voice!<br>I have been with you this whole time, said Tiger.`,
  `Ready to fly home? asked Tiger. They flew through the stars to ${hometown}.<br>I am always in your heart, said Tiger.`
];

const storyTexts = lines.map((text, i) => ({
  pageNumber: i + 1,
  text,
  characterName: childName,
  hometown,
  validated: true,
}));

// 2) Pose name map (for HTML alt/fallbacks)
const poseNames = [
  'walking',                 // 1
  'walking-looking-higher',  // 2
  'looking',                 // 3
  'floating',                // 4
  'walking-looking-down',    // 5
  'jogging',                 // 6
  'looking',                 // 7
  'sitting-eating',          // 8
  'crouching',               // 9
  'crawling-moving-happy',   // 10
  'surprised-looking-up',    // 11
  'surprised'                // 12
];

// 3) Ensure processedImages exists (12 canonical _nobg files) if missing
let processedImages = Array.isArray(order.processedImages) && order.processedImages.length
  ? order.processedImages
  : Array.from({ length: 12 }, (_, i) => {
      const poseNumber = i + 1;
      const padded = String(poseNumber).padStart(2, '0');
      const fileName = `characters_${hash}_pose${padded}_nobg.png`;
      const r2Path = `${BASE_PREFIX}/${hash}/${fileName}`;
      const publicUrl = `${publicR2Url}/${r2Path}`;
      return {
        poseNumber,
        fileName,
        r2Path,
        publicUrl,
        briaProcessed: true,
        briaStatus: 'COMPLETED',
        processingError: false,
      };
    });

// 4) Ensure characterImages exists; build it from processedImages if needed
// CRITICAL: Use backend proxy URLs, not publicR2Url direct URLs
// Get backendUrl from order context
let backendUrl = order.backendUrl;
if (!backendUrl) {
  try {
    const ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {};
    backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
  } catch {
    backendUrl = 'https://admin.littleherolabs.com';
  }
}

if (!order.characterImages || !Array.isArray(order.characterImages.poses)) {
  // Build poses from processedImages, ensuring correct pose-to-page mapping
  // processedImages come from 2B manifest with poseNumber 1-12
  // These should map directly to pages 1-12 (page 13 has animal only, page 14 has character + animal)
  const poses = processedImages
    .filter(pi => Number.isFinite(Number(pi.poseNumber)) && pi.poseNumber >= 1 && pi.poseNumber <= 12)
    .sort((a, b) => Number(a.poseNumber) - Number(b.poseNumber))
    .map(pi => {
      const poseNum = Number(pi.poseNumber);
      // Use backend proxy URL if available, otherwise fall back to publicUrl
      const imagePath = pi.publicUrl || (pi.r2Path ? `${backendUrl}/api/assets/${pi.r2Path}` : null);
      return {
        poseNumber: poseNum,
        poseFilename: poseNames[poseNum - 1] || `pose${String(poseNum).padStart(2, '0')}`,
        imagePath: imagePath,
        pageNumber: poseNum,    // NOTE: This is the pose's own number, not the page it appears on (see PAGE_TO_POSE_MAP in Generate Complete HTML)
        validated: !pi.processingError,
      };
    });

  order.characterImages = {
    base: `${backendUrl}/api/assets/${BASE_PREFIX}/${hash}/base-character.png`,
    poses,
  };
}

// 5) Return merged payload for HTML node
return [{
  json: {
    ...order,
    publicR2Url,
    backendUrl,
    storyTexts,
    processedImages,
  }
}];

// Build only the page blocks for PDFMonkey {{ pages_html }}
const order = $input.first().json;

// Get backendUrl from order context or extract from upstream
let backendUrl = order.backendUrl;
if (!backendUrl) {
  try {
    const ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {};
    backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
  } catch {
    backendUrl = 'https://admin.littleherolabs.com';
  }
}

// Construct text box overlay URL using backend proxy
// Uses standard-box.png for all pages
const getTextBoxOverlayUrl = () => {
  const r2Key = `book-mvp-simple-adventure/overlays/text-boxes/standard-box.png`;
  return `${backendUrl}/api/assets/${r2Key}`;
};

// FONT_URL still null for now (to be implemented if needed)
const FONT_URL = null;

// helpers
const findBg   = (i) => order.backgroundImages?.find(b => b.pageNumber === i)?.imagePath || '';
const findTxt  = (i) => (order.storyTexts?.find(s => s.pageNumber === i)?.text || '').replace(/\n/g,'<br>');
const findTextBoxOverlay = () => getTextBoxOverlayUrl();

// Pose lookup with explicit page-to-pose mapping
// CRITICAL: Page 7 uses pose 3 (looking), not pose 7!
// Pages 8-12 use poses 7-11 respectively (pose number = page number - 1)
const PAGE_TO_POSE_MAP = {
  1: 1,   // walking
  2: 2,   // walking-looking-higher
  3: 3,   // looking
  4: 4,   // floating
  5: 5,   // walking-looking-down
  6: 6,   // jogging
  7: 3,   // looking (reuse pose 3 from page 3)
  8: 7,   // sitting-eating
  9: 8,   // crouching
  10: 9,  // crawling-moving-happy
  11: 10, // surprised-looking-up
  12: 11, // surprised
  // 13: no character (animal only)
  14: 12  // flying/gliding
};

const findPose = (pageNum) => {
  if (pageNum === 13) return null; // SPEC: page 13 has animal only
  const poses = order.characterImages?.poses || [];
  const requiredPoseNumber = PAGE_TO_POSE_MAP[pageNum];
  if (!requiredPoseNumber) return null;
  // Find pose by poseNumber, not pageNumber
  let p = poses.find(p => Number(p.poseNumber) === requiredPoseNumber);
  // Fallback for page 14: try to find any flying pose
  if (!p && pageNum === 14) p = poses.find(p => /fly|flying/i.test(p.poseFilename || p.filename || ''));
  return p || null;
};

// px→in at 300dpi
const px2in = (px) => (px / 300).toFixed(4) + 'in';

// Original px map (absolute) for most pages
const CHAR = {
  1:  { left:1453, top:1938, w: 900, flip:  1 },
  2:  { left:1403, top:2091, w: 950, flip:  1 },
  3:  { left:1275, top:2295, w: 900, flip:  1 },   // will be overridden
  4:  { left:1020, top:2142, w:1100, flip: -1 },   // will be overridden
  5:  { left:1250, top:2066, w: 900, flip: -1 },
  6:  { left:1326, top:2066, w: 900, flip:  1 },
  7:  { left:1199, top:1683, w: 900, flip: -1 },
  8:  { left:1453, top:2040, w:1400, flip:  1 },
  9:  { left:1428, top:2142, w:1100, flip: -1 },  // crouching - flipped to face right (scaleX(-1) flips horizontally)
  10: { left:1275, top:2295, w:1300, flip: -1 },
  11: { left:1964, top:2117, w: 500, flip:  1 },
  12: { left: 893, top:2142, w:1000, flip: -1 },
  // 13: no character
  14: { left: 893, top:1836, w:1500, flip:  1 },   // will be overridden w/ same numbers + class sprite
};

// === OVERRIDES from your snippet (absolute px, bottom-center anchor) ===
// page03
const OV3 = { left:1020, top:2142, w:1100, flip:-1, rotate:0 };
// page04
const OV4 = { left:1530, top:1734, w:1100, flip: 1, rotate:-20 };
// page14 (character)
const OV14C = { left:893, top:1836, w:1500, flip:1, rotate:0 };
// page14 (animal)
const OV14A = { left:1275, top:1964, w:1250 };

function charStyle(n){
  // apply overrides first
  if (n === 3) {
    return [
      `left:${px2in(OV3.left)}`,
      `top:${px2in(OV3.top)}`,
      `transform:translate(-50%,-100%) scaleX(${OV3.flip})`,
      `width:${px2in(OV3.w)}`,
      `z-index:11`
    ].join('; ') + ';';
  }
  if (n === 4) {
    return [
      `left:${px2in(OV4.left)}`,
      `top:${px2in(OV4.top)}`,
      `transform:translate(-50%,-100%) scaleX(${OV4.flip}) rotate(-20deg)`,
      `width:${px2in(OV4.w)}`,
      `z-index:11`
    ].join('; ') + ';';
  }
  if (n === 14) {
    return [
      `left:${px2in(OV14C.left)}`,
      `top:${px2in(OV14C.top)}`,
      `transform:translate(-50%,-100%) scaleX(${OV14C.flip})`,
      `width:${px2in(OV14C.w)}`,
      `z-index:11`
    ].join('; ') + ';';
  }
  // fallback to your original px map (converted) for other pages
  const c = CHAR[n];
  if (!c) return '';
  return [
    `left:${px2in(c.left)}`,
    `top:${px2in(c.top)}`,
    `transform:translate(-50%,-100%) scaleX(${c.flip})`,
    `width:${px2in(c.w)}`,
    `z-index:11`
  ].join('; ') + ';';
}

// Animals - use order.animalImages and order.animalDisplayName
function animalHTML(i){
  const animalImages = order.animalImages || {};
  const animalDisplayName = order.animalDisplayName || 'Tiger';

  if (i === 13) {
    const src = animalImages.appears || '';
    if (!src) return '';

    // Tuned for PDFMonkey with bottom-center anchor:
    // Positioned over the yellow circle/shadow on the ground
    // Adjusted: moved down 7% and left 12% from original position
    const leftPx = 1344;    // ≈ 53% of 2550 (was 1650, moved left 12%)
    const topPx  = 2078;    // ≈ 81% of 2550 (was 1900, moved down 7%)
    const wPx    = 1800;    // ≈ 6.0in at 300dpi

    return `
      <div class="animal" style="
        left:${px2in(leftPx)};
        top:${px2in(topPx)};
        transform:translate(-50%,-100%);
        width:${px2in(wPx)};
        z-index:9;">
        <img class="sprite" src="${src}" alt="${animalDisplayName} Appears">
      </div>`;
  }

  if (i === 14) {
    const src = animalImages.flying || '';
    if (!src) return '';
    // From positioning doc
    const left = px2in(1275), top = px2in(1964), w = px2in(1250);
    return `
      <div class="animal" style="
        left:${left};
        top:${top};
        transform:translate(-50%,-100%);
        width:${w};
        z-index:9;">
        <img class="sprite" src="${src}" alt="${animalDisplayName} Flying">
      </div>`;
  }
  return '';
}


// Inline font so it applies even when only {{ pages_html }} is rendered
const fontStyle = `
<style>
@font-face {
  font-family: 'CustomBook';
  src: url('${FONT_URL}') format('truetype');
  font-display: swap;
}
.text-content, body { 
  font-family: 'CustomBook', Arial, sans-serif; 
  font-size: 18px;
  line-height: 1.3;
}
.text-content {
  font-size: 18px;
  line-height: 1.3;
  padding: 0.15in 0.2in;
  box-sizing: border-box;
}
</style>`.trim();

let pages_html = fontStyle + '\n';

for (let i = 1; i <= 14; i++) {
  const bg   = findBg(i);
  const pose = findPose(i);
  const text = findTxt(i);
  const textBoxOverlay = findTextBoxOverlay();

  pages_html += `
<div class="book-page" id="page-${i}">
  <div class="page-bg" style="background-image:url('${bg}');"></div>

  <div class="text-box" style="background-image:url('${textBoxOverlay}')">
    <div class="text-content">${text}</div>
  </div>

